let pets=[], petById={}, owned={}, coins=500, freeHatches=5, history=[], soundOn=true, activeFilter='Alles', busy=false, toastTimer;
rarities.forEach((r,ri)=>{petData[r.name].forEach((p,i)=>{const pet={id:`${ri}-${i}`,name:p[0],emoji:p[1],desc:p[2],rarity:r.name,color:r.color};pets.push(pet);petById[pet.id]=pet;});});
function loadSave(){try{const s=JSON.parse(localStorage.getItem('eggventure-save-v1')||'{}');coins=Number.isFinite(s.coins)?s.coins:500;freeHatches=Number.isFinite(s.freeHatches)?s.freeHatches:5;owned=s.owned&&typeof s.owned==='object'?s.owned:{};history=Array.isArray(s.history)?s.history.filter(x=>petById[x.id]).slice(0,4):[];}catch(e){coins=500;freeHatches=5;owned={};history=[];}}
function save(){try{localStorage.setItem('eggventure-save-v1',JSON.stringify({coins,freeHatches,owned,history}));}catch(e){}}
function render(){document.getElementById('coins').textContent=coins.toLocaleString('nl-NL');const count=pets.reduce((n,p)=>n+(owned[p.id]?1:0),0),pct=Math.round(count/75*100);document.getElementById('ownedCount').textContent=count;document.getElementById('progressText').textContent=pct+'%';document.getElementById('progressRing').style.setProperty('--progress',pct+'%');document.getElementById('progressBar').style.width=pct+'%';document.getElementById('indexSubtitle').textContent=`${count} van 75 magische pets ontdekt`;
 document.getElementById('rarityRow').innerHTML=rarities.map(r=>`<div class="rarity-pill" style="--rarity:${r.color}"><i class="rarity-dot"></i>${r.name}</div>`).join('');
 document.getElementById('tierList').innerHTML=rarities.map(r=>{const list=pets.filter(p=>p.rarity===r.name),got=list.filter(p=>owned[p.id]).length,pc=got/list.length*100;return `<div class="tier-row" style="--rarity:${r.color}"><span class="tier-icon">${r.icon}</span><strong>${r.name}</strong><span class="count">${got}/${list.length}</span><span class="mini-bar"><span style="width:${pc}%"></span></span></div>`;}).join('');
 document.getElementById('recentList').innerHTML=history.length?`<div class="recent-list">${history.map((h,i)=>{const p=petById[h.id];return `<div class="recent-item"><div class="recent-emoji">${p.emoji}</div><div class="recent-info"><b>${p.name}</b><small style="color:${p.color}">${p.rarity}</small></div>${h.isNew?'<span class="new-tag">NIEUW</span>':''}</div>`;}).join('')}</div>`:`<div class="empty-recent"><div class="empty-icon">🥚</div>Nog geen pets ontdekt.<br>Broed je eerste ei!</div>`;
 const btn=document.getElementById('hatchButton');btn.disabled=busy||(!freeHatches&&coins<100);btn.innerHTML=busy?'✨ &nbsp; Ei broedt...':freeHatches?`🥚 &nbsp; Broed een ei <span>· GRATIS (${freeHatches})</span>`:`🥚 &nbsp; Broed een ei <span>· 100 🪙</span>`;
 if(document.getElementById('indexOverlay').classList.contains('open'))renderIndex();}
function renderIndex(){const filters=['Alles',...rarities.map(r=>r.name)];document.getElementById('filters').innerHTML=filters.map(f=>`<button class="filter ${f===activeFilter?'selected':''}" data-filter="${f}">${f==='Alles'?'🌈 ':''}${f}${f==='Alles'?` (${pets.length})`:''}</button>`).join('');const list=pets.filter(p=>activeFilter==='Alles'||p.rarity===activeFilter);document.getElementById('petGrid').innerHTML=list.map(p=>{const got=!!owned[p.id];return `<div class="pet-card ${got?'owned':'locked'}" style="--rarity:${p.color}" title="${got?p.desc:'Nog niet ontdekt'}"><span class="pet-emoji">${got?p.emoji:'?'}</span><span class="pet-name">${got?p.name:'???'}</span><span class="pet-rarity" style="color:${got?p.color:'#68768d'}">${p.rarity}</span></div>`;}).join('');}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100);}
function rarityPick(){const roll=Math.random()*100;let total=0;for(const r of rarities){total+=r.chance;if(roll<total)return r;}return rarities[0];}
function playTone(freq=520,duration=.12){if(!soundOn)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=new C(),o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.055,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+duration);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+duration);o.onended=()=>ctx.close();}catch(e){}}
function hatch(){if(busy)return;if(!freeHatches&&coins<100){toast('Niet genoeg munten!');return;}busy=true;if(freeHatches)freeHatches--;else coins-=100;render();playTone(300,.24);const card=document.getElementById('gameCard');card.classList.add('hatching');setTimeout(()=>{card.classList.remove('hatching');busy=false;const r=rarityPick(),pool=pets.filter(p=>p.rarity===r.name),pet=pool[Math.floor(Math.random()*pool.length)],isNew=!owned[pet.id];if(isNew){owned[pet.id]=1;}else{coins+=r.dupe;toast(`Dubbel! +${r.dupe} munten terug`);}history.unshift({id:pet.id,isNew});history=history.slice(0,4);save();render();showResult(pet,r,isNew);playTone(isNew?720:430,.2);},850);}
function showResult(p,r,isNew){const card=document.getElementById('resultCard');card.innerHTML=`<div class="result-spark">${isNew?'✦ NIEUWE ONTDEKKING ✦':'✦ DUBBELE VONDST ✦'}</div><div class="result-egg">🥚</div><div class="result-pet">${p.emoji}</div><h2 id="resultName">${p.name}</h2><p class="result-desc">${p.desc}</p><span class="result-badge" style="--rarity:${r.color}">${r.icon} ${r.name} · ${r.chance}% kans</span><div class="result-reward">${isNew?'🎉 Toegevoegd aan je pet-index!':`🪙 +${r.dupe} munten voor je dubbele pet`}</div><button class="result-continue" id="continueButton">${pets.every(x=>owned[x.id])?'Alles verzameld! ✨':'Verder spelen ✨'}</button>`;document.getElementById('resultOverlay').classList.add('open');document.getElementById('continueButton').onclick=()=>document.getElementById('resultOverlay').classList.remove('open');}
function openIndex(){activeFilter='Alles';document.getElementById('indexOverlay').classList.add('open');renderIndex();}
document.getElementById('hatchButton').addEventListener('click',hatch);document.getElementById('openIndex').addEventListener('click',openIndex);document.getElementById('openIndexRecent').addEventListener('click',openIndex);document.getElementById('closeIndex').addEventListener('click',()=>document.getElementById('indexOverlay').classList.remove('open'));document.getElementById('filters').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;activeFilter=b.dataset.filter;renderIndex();});document.getElementById('indexOverlay').addEventListener('click',e=>{if(e.target.id==='indexOverlay')e.currentTarget.classList.remove('open');});document.getElementById('resultOverlay').addEventListener('click',e=>{if(e.target.id==='resultOverlay')e.currentTarget.classList.remove('open');});document.getElementById('soundButton').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'🔊':'🔇';e.currentTarget.setAttribute('aria-label',soundOn?'Geluid uitzetten':'Geluid aanzetten');if(soundOn)playTone(560,.1);});document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('.overlay.open').forEach(x=>x.classList.remove('open'));}});
loadSave();render();
</script>
</body>
</html>

